// vector cube from ingagard:   https://www.shadertoy.com/view/4djfWt


#define rotate(a) mat2(cos(a),-sin(a),sin(a),cos(a))

const float size = 100.0;
const vec3 objectStartPos = vec3(0, 0, -50.0);    
const float camRange=1000.0;
const vec4 quads[6] = vec4[](vec4(0,1,2,3),vec4(7,6,5,4),vec4(3,7,4,0),vec4(2,1,5,6),vec4(4,5,1,0),vec4(6,7,3,2));

float scale[8];
vec3 projPos[8];    
vec3 edges[24];

//---------------------------------------------------------
void Line(vec2 screenCoord, vec2 p1, vec2 p2, float thickness, vec3 color, inout vec3 pixel) {
  float a = distance(p1, screenCoord);
  float b = distance(p2, screenCoord);
  float c = distance(p1, p2);
  if ( a >= c || b >=  c ) return;

  float p = (a + b + c) * 0.5;
  float dist = 2.0 / c * sqrt( p * ( p - a) * ( p - b) * ( p - c));

  if (dist<thickness)
    pixel = color; // mix(pixel, color, 1.0/max(1.0, dist*3.0));
}

//---------------------------------------------------------
bool isLeft(vec2 a, vec2 b, vec2 c) {  // point c to the left of line a-b?
  return (b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x) < 0.;
}
//---------------------------------------------------------

float ptLineDistance(vec2 pt,vec2 lineP1,vec2 lineP2) {
    vec2 ab = lineP2-lineP1;
    vec2 be = pt-lineP2;     
    if(dot(ab,be) > 0.) return length(be);

    vec2 ae = pt-lineP1;
    if(dot(ab,ae) < 0.) return length(ae); 
    return abs(ab.x * ae.y - ab.y * ae.x) / length(ab);
}

//---------------------------------------------------------
void mainImage(out vec4 O, vec2 U) {
  float rot = float(iTime) * 0.9;
  vec2 uv = (U.xy / iResolution.xy);
  vec3 camPos = vec3(0, 0, 30.0);    

  #define P +1.0
  #define N -0.02 //1.0  
  vec3 verts[8] = vec3[](
    vec3(N,N,N),vec3(N,N,P),vec3(P,N,P),vec3(P,N,N), 
    vec3(N,P,N),vec3(N,P,P),vec3(P,P,P),vec3(P,P,N));

  for (int i=0; i<8; i++) {           
      verts[i].xz *= rotate(rot * 0.1); 
      verts[i].yz *= rotate(rot * 0.7);  
      verts[i].xy *= rotate(rot * 0.2);  
      verts[i] += objectStartPos;
  }

  vec3 halfRes = vec3(iResolution.x*0.5, iResolution.y*0.5, 0);   
  for (int i=0; i<8; i++)  {                            
    float camDistance = distance(verts[i], camPos);
    scale[i] = (camRange/camDistance)*0.1;
    projPos[i] = verts[i]-camPos;
    projPos[i]*=size*scale[i];    
    projPos[i]+= halfRes;
  }

  float range = 0.0; // 0 = no side shrinkage.  1 = shrunk to zero size

  vec2 center = iResolution.xy * 0.5;

  for (int i=0; i<6; i++) {
    vec3 center = (projPos[int(quads[i].x)]+projPos[int(quads[i].y)]+projPos[int(quads[i].z)]+projPos[int(quads[i].w)])/4.0;           
    edges[i*4 + 0]=projPos[int(quads[i].x)]+((center-projPos[int(quads[i].x)])*range);
    edges[i*4 + 1]=projPos[int(quads[i].y)]+((center-projPos[int(quads[i].y)])*range);
    edges[i*4 + 2]=projPos[int(quads[i].z)]+((center-projPos[int(quads[i].z)])*range);
    edges[i*4 + 3]=projPos[int(quads[i].w)]+((center-projPos[int(quads[i].w)])*range);            
  }

  vec3 color = 0.5 + 0.5*cos(iTime+uv.xyx + vec3(0,2,4));
  vec2 screenCoord = vec2(U.x, iResolution.y-U.y);

  const float lineWidth = 1.0;
  const vec3 lineColor = vec3(1.0);  //white colored edges
  for (int i=0; i<6; i++) {    
    Line(screenCoord, edges[i*4 + 0].xy, edges[i*4 + 1].xy, lineWidth, lineColor, color);  
    Line(screenCoord, edges[i*4 + 1].xy, edges[i*4 + 2].xy, lineWidth, lineColor, color);  
    Line(screenCoord, edges[i*4 + 2].xy, edges[i*4 + 3].xy, lineWidth, lineColor, color);  
    Line(screenCoord, edges[i*4 + 3].xy, edges[i*4 + 0].xy, lineWidth, lineColor, color);
  }

  O.xyz = color;

  for (int i=0; i<6; i++) {    
    bool inside = 
        isLeft(edges[i*4 + 0].xy,edges[i*4 + 1].xy,screenCoord) && 
        isLeft(edges[i*4 + 1].xy,edges[i*4 + 2].xy,screenCoord) && 
        isLeft(edges[i*4 + 2].xy,edges[i*4 + 3].xy,screenCoord) && 
        isLeft(edges[i*4 + 3].xy,edges[i*4 + 0].xy,screenCoord); 
    if(!inside) continue;

    vec2 tuv = U;
    vec2 sz;

    if(i<3) sz = vec2(textureSize(iChannel1,0)); else sz = vec2(textureSize(iChannel2,0));

    float dx1 = ptLineDistance(screenCoord,edges[i*4 + 0].xy,edges[i*4 + 1].xy);
    float dx2 = ptLineDistance(screenCoord,edges[i*4 + 2].xy,edges[i*4 + 3].xy);
    tuv.x = sz.x * dx1/(dx1+dx2);

    float dy1 = ptLineDistance(screenCoord,edges[i*4 + 0].xy,edges[i*4 + 3].xy);
    float dy2 = ptLineDistance(screenCoord,edges[i*4 + 1].xy,edges[i*4 + 2].xy);
    tuv.y = sz.y * dy1/(dy1+dy2);
    vec3 q;

    if(i < 3) q = texelFetch(iChannel1,ivec2(tuv),0).xyz; else
     q = texelFetch(iChannel2,ivec2(tuv),0).xyz;

    const float s = 1.5;
    if(q.z < q.x*s && q.z < q.y*s) O.xyz = q;

//     O.xyz = q;
  }
}
